const store=new Map,loaded=new Set,work=new Map,hot=new Map;
function str(k){return Math.floor(k/1000)+':'+(k%1000)}
const pages=Array.from({length:M.count+1},(_,n)=>{
 const q=M.pg[n];if(!q)return {b:-1,blank:true,start:'',end:'',cols:[[],[]],physical:true,pdfPage:n};
 return {b:q[0],start:str(q[1]),end:str(q[2]),cols:[[],[]],physical:true,pdfPage:n,displayPage:n<953?n-8:n-952,testament:n<953?'OT':'NT',firstOfBook:M.books[q[0]].first===n};
});
const meta={edition:M.edition,books:M.books,pages,physical:true,pdfCount:M.count,stats:{books:M.books.length,chapters:1189,verses:31102}};
function readTags(n){
 const page=M.pg[n];if(!page)return [];
 const res=hot.get(n);if(res)return res;
 const raw=atob(page[4]);let pos=0,out=[],cache=new Map;
 function read(){let a=0,factor=1;for(;;){if(pos>=raw.length)throw Error('纸本节索引截断');const c=raw.charCodeAt(pos++);a+=(c&127)*factor;if(c<128)return a;factor*=128;if(factor>268435456)throw Error('纸本节索引无效');}}
 while(pos<raw.length){const count=read(),v=read();if(!count||out.length+count>page[3])throw Error('纸本节索引损坏');
  let info=cache.get(v);if(!info){const role=M.roles[v%8],k=Math.floor(v/8),end=role==='heading'?0:M.books[page[0]].joined[k],ref=v?str(k)+(end?'-'+end:''):'';
   info=Object.freeze({role,ref,group:v?role==='heading'?'heading:'+ref:'verse:'+ref:null});cache.set(v,info)}
  for(let j=0;j<count;j++)out.push(info);
 }
 if(out.length!==page[3])throw Error('节号索引与印页不相符');
 hot.set(n,out);if(hot.size>10)hot.delete(hot.keys().next().value);return out;
}
function installPack(k,raw){k=String(k);if(!(k in M.packs))throw Error('未知印页包 '+k);if(loaded.has(k))return;
 const entries=Object.entries(raw);for(const [s,pair] of entries){const n=Number(s);if((n&1)||!Number.isInteger(n)||Math.floor(n/32)!==+k||!Array.isArray(pair)||pair.length!==2)throw Error('印页包错误');
  for(let j=0;j<2;j++){const p=pair[j],t=M.pg[n+j];if(p===null?!t:p&&t&&p[0]===n+j&&p[3].length===t[3])continue;throw Error('印页文字数与索引不符 '+(n+j))}}
 for(const [s,pair] of entries){const n=Number(s);for(let j=0;j<2;j++)store.set(n+j,pair[j])}loaded.add(k);
}
async function load(n){if(!M.pg[n])return null;if(store.has(n))return store.get(n);const k=Math.floor(n/32);
 if(!work.has(k)){const p=fetch('./paper-pages/'+M.packs[k]).then(r=>{if(!r.ok)throw Error('加载纸本失败');return r.json()}).then(raw=>installPack(k,raw));work.set(k,p);p.catch(()=>work.delete(k))}
 await work.get(k);return store.get(n);
}
function finalize(){if(loaded.size!==Object.keys(M.packs).length||Object.keys(M.pg).some(n=>!store.get(+n)))throw Error('原纸经文数据未加载完整');return meta}
function lookup(book,ref){const b=M.books.find(b=>b.code===book||b.name===book),a=/^(\d+):(\d+)(?:[-–]\d+)?$/.exec(String(ref));if(!a||!b)return null;
 return b.versePages[+a[1]-1]?.[+a[2]-1]||null}
const api={edition:M.edition,sha:M.sha,count:M.count,packs:M.packs,books:M.books,pages,meta,lookup,get:n=>M.pg[n]?store.get(+n):null,tags:readTags,metaFor:(n,i)=>readTags(n)[i]||null,load,installPack,finalize};
